using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Windows.Forms;using Frociart;
internal static class SourceTargetUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Pump(){var until=DateTime.UtcNow.AddMilliseconds(180);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(3);}}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();var document=FlowPseudocode.Decode("STAMPA 1");foreach(var target in FlowSourceTarget.All)foreach(bool dark in new[]{true,false})using(var dialog=new SourceCodeDialog(document,null,target)){Ui.SetDarkMode(dark,false);dialog.Size=new Size(640,480);dialog.Show();Pump();var layout=(TableLayoutPanel)dialog.Controls[0];var intro=(Label)layout.GetControlFromPosition(0,0);int measured=TextRenderer.MeasureText(intro.Text,intro.Font,new Size(intro.Width,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height;Check(intro.Height>=measured,"Minimum source dialog fits compiler instructions: "+target.Name);Check(dialog.Editor.Height>=90&&dialog.Copy.Visible&&dialog.Save.Visible,"Minimum source dialog retains readable editor and controls: "+target.Name);Check(dialog.Source.Text.Length>dialog.Editor.Text.Length,"Support stays out of compact program preview: "+target.Name);Check(dialog.Support.Visible&&dialog.Support.Height>=24,"Support toggle is actually visible: "+target.Name);dialog.Close();}
 Console.WriteLine("SOURCE_TARGET_UI PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
